// Keep the bridge independent of generated Wails files (regenerated by wails build).
function call(method, ...args) {
  const app = window.go?.main?.App
  if (!app?.[method]) return Promise.reject(new Error('Cloud Sync is unavailable'))
  return app[method](...args)
}
export const SetCloudSyncEnabled = enabled => call('SetCloudSyncEnabled', enabled)
export const GetCloudSyncStatus = () => call('GetCloudSyncStatus')
export const GenerateCloudSyncToken = () => call('GenerateCloudSyncToken')
export const TestCloudConnection = token => call('TestCloudConnection', token)
export const ConnectCloudSync = token => call('ConnectCloudSync', token)
export const DisconnectCloudSync = () => call('DisconnectCloudSync')
export const SetCloudSyncPreferences = (automatic, deviceName) => call('SetCloudSyncPreferences', automatic, deviceName)
export const CloudSyncNow = () => call('CloudSyncNow')
export const CheckCloudSyncOnFocus = () => call('CheckCloudSyncOnFocus')
export const ResolveCloudSync = (choice, revision, fingerprint) =>
  call('ResolveCloudSync', choice, revision, fingerprint)
export const CopyCloudSyncToken = () => call('CopyCloudSyncToken')
